const TTL = { m: 8, d: 6, f: 8 };

async function hmac(key, msg) {
  const k = await crypto.subtle.importKey('raw', typeof key === 'string' ? new TextEncoder().encode(key) : key, { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  return new Uint8Array(await crypto.subtle.sign('HMAC', k, new TextEncoder().encode(msg)));
}
async function validInit(init, token) {
  try {
    const p = new URLSearchParams(init); const hash = p.get('hash'); p.delete('hash');
    if (!hash || Date.now() / 1000 - +p.get('auth_date') > 86400) return false;
    const str = [...p.entries()].sort(([a], [b]) => a < b ? -1 : 1).map(([k, v]) => `${k}=${v}`).join('\n');
    const sig = await hmac(await hmac('WebAppData', token), str);
    return [...sig].map(b => b.toString(16).padStart(2, '0')).join('') === hash;
  } catch { return false; }
}

/* ============================================================
   ADMIN PANEL — helper functions
   Env vars needed (Cloudflare Pages > Settings > Environment Variables):
     ADMIN_PASS      -> admin panel login password (required)
   Binding needed (Cloudflare Pages > Settings > Functions > D1 database bindings):
     BP_DB           -> D1 database binding (table bp_settings ကို အလိုအလျောက် ဆောက်ပေးမယ်)
     BP_KV           -> (optional/ဟောင်း) KV — D1 မရှိမှသာ fallback
   ============================================================ */

const b64u = buf => {
  let bin = '';
  const b = buf instanceof Uint8Array ? buf : new Uint8Array(buf);
  for (let i = 0; i < b.length; i++) bin += String.fromCharCode(b[i]);
  return btoa(bin).replace(/=+$/, '').replace(/\+/g, '-').replace(/\//g, '_');
};
const hex = buf => [...new Uint8Array(buf)].map(x => x.toString(16).padStart(2, '0')).join('');

function cookieGet(req, name) {
  const c = req.headers.get('cookie') || '';
  const m = c.match(new RegExp('(?:^|;\\s*)' + name + '=([^;]+)'));
  return m ? decodeURIComponent(m[1]) : '';
}

async function sessionSign(env, payload) {
  const body = b64u(new TextEncoder().encode(JSON.stringify(payload)));
  const sig = hex(await hmac(env.ADMIN_PASS || 'dev', body));
  return body + '.' + sig;
}
async function sessionVerify(env, token) {
  try {
    const [body, sig] = (token || '').split('.');
    if (!body || !sig) return false;
    const want = hex(await hmac(env.ADMIN_PASS || 'dev', body));
    if (want !== sig) return false;
    const pad = body.replace(/-/g, '+').replace(/_/g, '/');
    const json = JSON.parse(atob(pad + '==='.slice((pad.length + 3) % 4)));
    return json.exp > Date.now() / 1000;
  } catch { return false; }
}
async function isAdmin(req, env) {
  if (!env.ADMIN_PASS) return false;
  return sessionVerify(env, cookieGet(req, 'bp_admin'));
}

