/* ---------- storage: Cloudflare D1 (BP_DB) — KV (BP_KV) ကို ဟောင်းဒေတာ ဖတ်ဖို့/ D1 မရှိရင် fallback အဖြစ်သာ ---------- */
let dbReady = false;
async function dbInit(env) {
  if (dbReady) return;
  await env.BP_DB.prepare('CREATE TABLE IF NOT EXISTS bp_settings (k TEXT PRIMARY KEY, v TEXT NOT NULL)').run();
  dbReady = true;
}
async function getSettings(env) {
  try {
    let raw = null;
    if (env.BP_DB) {
      await dbInit(env);
      const row = await env.BP_DB.prepare('SELECT v FROM bp_settings WHERE k = ?').bind(SET_KEY).first();
      raw = row ? row.v : null;
      if (raw == null && env.BP_KV) raw = await env.BP_KV.get(SET_KEY); // KV ကနေ D1 ကို ပြောင်းစဉ် ဟောင်းဒေတာ
    } else if (env.BP_KV) raw = await env.BP_KV.get(SET_KEY);
    return raw ? Object.assign({}, DEFAULT_SET, JSON.parse(raw)) : DEFAULT_SET;
  } catch { return DEFAULT_SET; }
}
async function setSettings(env, obj) {
  const val = JSON.stringify(obj);
  if (env.BP_DB) {
    await dbInit(env);
    await env.BP_DB.prepare('INSERT INTO bp_settings (k, v) VALUES (?, ?) ON CONFLICT(k) DO UPDATE SET v = excluded.v').bind(SET_KEY, val).run();
    return;
  }
  if (!env.BP_KV) throw new Error('BP_DB (D1) binding မရှိပါ');
  try { await env.BP_KV.put(SET_KEY, val); }
  catch (e) { if (/limit exceeded/i.test(String(e && e.message))) throw new Error('KV write ကန့်သတ်ချက် ပြည့်သွားပါပြီ — D1 (BP_DB) ကို bind လုပ်ပြီး သုံးပါ။'); throw e }
}

