/* ============================================================
   IMAGE BANNER SLIDER (Live tab ရဲ့ အပေါ်) — admin preview နဲ့ app မှာ code တူတူသုံးထားတယ်
   Admin က တစ်ကြောင်းကို  ပုံလင့် | (link) | (caption)  ပုံစံနဲ့ ထည့်၊ ပုံ ၁ ပုံပဲဆိုရင် static၊ ၂ ပုံနဲ့အထက်ဆို ၄ စက္ကန့်တစ်ခါ အလိုအလျောက်ရွေ့
   ============================================================ */
const BP_BANNER_CSS = `.bpw{position:relative;margin:0 0 14px}
.bpsl{display:flex;overflow-x:auto;scroll-snap-type:x mandatory;scrollbar-width:none;-webkit-overflow-scrolling:touch;border-radius:16px;aspect-ratio:16/7;background:#17181E;box-shadow:0 0 0 1px rgba(255,255,255,.08)}
.bpsl::-webkit-scrollbar{display:none}
.bps{position:relative;flex:0 0 100%;width:100%;scroll-snap-align:center;scroll-snap-stop:always;display:block;overflow:hidden}
.bps img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;display:block;-webkit-user-drag:none;user-select:none}
.bpc{position:absolute;left:0;right:0;bottom:0;padding:26px 14px 11px;background:linear-gradient(transparent,rgba(0,0,0,.78));color:#fff;font-size:13px;font-weight:700;line-height:1.3;text-shadow:0 1px 2px rgba(0,0,0,.6)}
.bpd{display:flex;justify-content:center;gap:5px;margin-top:8px;pointer-events:none}
.bpd i{width:6px;height:6px;border-radius:99px;background:rgba(255,255,255,.28);transition:width .25s,background .25s}
.bpd i.on{width:18px;background:#F5F500}`;
const BP_BANNER_JS = `(function(){
function esc(s){return String(s).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
var isU=function(x){return /^https?:/i.test(x||'')};
window.bpBannerParse=function(t){var o=[];String(t||'').split('\\n').forEach(function(l){var p=l.split('|').map(function(x){return x.trim()});if(!isU(p[0]))return;var link=isU(p[1])?p[1]:'';o.push({img:p[0],link:link,cap:(link?p[2]:p[1])||''})});return o.slice(0,20)};
window.bpBannerHtml=function(items){if(!items||!items.length)return '';var s=items.map(function(it,i){var cap=it.cap?'<span class="bpc">'+esc(it.cap)+'</span>':'';var inner='<img src="'+esc(it.img)+'" alt="" loading="'+(i?'lazy':'eager')+'" referrerpolicy="no-referrer" draggable="false" onerror="bpImgErr(this)">'+cap;return it.link?'<a class="bps" href="'+esc(it.link)+'" target="_blank" rel="noopener">'+inner+'</a>':'<div class="bps">'+inner+'</div>'}).join('');var d=items.length<2?'':'<div class="bpd">'+items.map(function(_,i){return '<i'+(i?'':' class="on"')+'></i>'}).join('')+'</div>';return '<div class="bpw"><div class="bpsl">'+s+'</div>'+d+'</div>'};
window.bpImgErr=function(im){var w=im.closest('.bpw'),s=im.closest('.bps');if(s)s.remove();if(!w)return;var c=w.querySelector('.bpsl'),n=c?c.children.length:0;if(!n){w.remove();return}var d=w.querySelector('.bpd');if(d){if(n<2)d.remove();else d.innerHTML=Array(n+1).join('<i></i>')}};
var pause=0,idx=0;
function hold(e){if(e.target&&e.target.closest&&e.target.closest('.bpsl'))pause=Date.now()+7000}
document.addEventListener('touchstart',hold,true);document.addEventListener('pointerdown',hold,true);document.addEventListener('wheel',hold,true);
document.addEventListener('scroll',function(e){var c=e.target;if(!c||!c.classList||!c.classList.contains('bpsl')||!c.clientWidth)return;var i=Math.round(c.scrollLeft/c.clientWidth),d=c.parentNode.querySelectorAll('.bpd i');idx=i;for(var k=0;k<d.length;k++)d[k].className=k===i?'on':''},true);
setInterval(function(){if(document.hidden||Date.now()<pause)return;var cs=document.querySelectorAll('.bpsl');for(var k=0;k<cs.length;k++){var c=cs[k],n=c.children.length;if(n<2||!c.clientWidth)continue;var i=Math.round(c.scrollLeft/c.clientWidth);c.scrollTo({left:((i+1)%n)*c.clientWidth,behavior:'smooth'})}},4000);
/* app က tab/refresh ကြောင့် re-render လုပ်တိုင်း လက်ရှိ slide ကို ပြန်ထားပေး */
if(window.MutationObserver){new MutationObserver(function(){var cs=document.querySelectorAll('.bpsl:not([data-r])');for(var k=0;k<cs.length;k++){var c=cs[k];c.setAttribute('data-r','1');if(idx&&idx<c.children.length&&c.id!=='x'){c.style.scrollSnapType='none';c.scrollLeft=idx*c.clientWidth;c.style.scrollSnapType='';var d=c.parentNode.querySelectorAll('.bpd i');for(var j=0;j<d.length;j++)d[j].className=j===idx?'on':''}}}).observe(document.body,{childList:true,subtree:true})}
})();`;
const BP_HEAD = `<meta name="theme-color" content="#09090b">
<link rel="icon" type="image/svg+xml" href="/favicon.svg"><link rel="icon" type="image/png" sizes="32x32" href="/favicon-32.png">
<link rel="apple-touch-icon" href="/apple-touch-icon.png"><link rel="manifest" href="/manifest.webmanifest">
<meta property="og:title" content="BallPwal"><meta property="og:image" content="/icon-512.png">`;
function brandAsset(path) {
  const h = { 'cache-control': 'public, max-age=86400' };
  if (path === '/manifest.webmanifest') return new Response(BP_MANIFEST, { headers: { ...h, 'content-type': 'application/manifest+json' } });
  if (path === '/favicon.svg') return new Response(BP_SVG.favicon, { headers: { ...h, 'content-type': 'image/svg+xml' } });
  let m = path.match(/^\/brand\/([a-z-]+)\.svg$/);
  if (m && BP_SVG[m[1]]) return new Response(BP_SVG[m[1]], { headers: { ...h, 'content-type': 'image/svg+xml' } });
  const png = path === '/favicon.ico' ? 'favicon-32.png' : path.slice(1);
  if (BP_PNG[png]) { const bin = Uint8Array.from(atob(BP_PNG[png]), c => c.charCodeAt(0)); return new Response(bin, { headers: { ...h, 'content-type': 'image/png' } }); }
  return null;
}
const adminBrand = (accent, big) => `<span class="bplogo" style="--h:${big ? 44 : 30}px" role="img" aria-label="BallPwal">${BP_FULL}</span>`;

const aField = (label, input, hint) => `<label class="block mt-4"><span class="block text-xs font-bold text-zinc-400 mb-1.5">${label}</span>${input}${hint ? `<span class="block text-[11px] text-zinc-500 mt-1.5">${hint}</span>` : ''}</label>`;
const aInput = (name, val, ph, type, req) => `<input type="${type || 'text'}" name="${name}" value="${AE(val || '')}" placeholder="${AE(ph || '')}" ${req ? 'required' : ''} class="w-full h-11 px-3.5 rounded-xl bg-zinc-900 ring-1 ring-white/10 text-white text-sm outline-none focus:ring-emerald-400 placeholder:text-zinc-600">`;
const aArea = (name, val, ph, req) => `<textarea name="${name}" placeholder="${AE(ph || '')}" ${req ? 'required' : ''} class="w-full min-h-[84px] px-3.5 py-3 rounded-xl bg-zinc-900 ring-1 ring-white/10 text-white text-sm outline-none focus:ring-emerald-400 placeholder:text-zinc-600 resize-y">${AE(val)}</textarea>`;
const aCard = (icon, title, body) => `<div class="rounded-2xl bg-zinc-900/70 ring-1 ring-white/5 p-5 mb-4"><div class="flex items-center gap-2 mb-3 text-emerald-400 font-bold text-[13px] tracking-wide uppercase">${icon}${title}</div>${body}</div>`;
const aBtn = (txt, icon, cls) => `<button type="submit" class="mt-5 w-full h-12 flex items-center justify-center gap-2 rounded-xl font-extrabold text-sm active:scale-[.98] transition ${cls || 'bg-emerald-500 text-zinc-950'}">${icon || ''}${txt}</button>`;

