function timeAgo(ts) {
  if (!ts) return 'တစ်ခါမှ မသိမ်းရသေးပါ';
  const s = Math.max(0, Math.floor(Date.now() / 1000) - ts);
  if (s < 60) return 'ခုနက လေးစက္ကန့်အလို';
  if (s < 3600) return Math.floor(s / 60) + ' မိနစ်အလို';
  if (s < 86400) return Math.floor(s / 3600) + ' နာရီအလို';
  return Math.floor(s / 86400) + ' ရက်အလို';
}
