    const r = await fetch(API.f(), { headers: { 'User-Agent': API_UA, Accept: 'application/json', Referer: 'https://fibcast.com/', Origin: 'https://fibcast.com' }, signal: ac.signal, cf: { cacheTtl: TTL.f, cacheEverything: true } });
    if (!r.ok) throw new Error('fc');
    const j = await r.json();
    const arr = (j && j.result && j.result.nowPlayingMatches) || [];
    if (!Array.isArray(arr)) throw new Error('fc');
