const nzs = s => String(s || '').toLowerCase().replace(/[^\p{L}\p{M}\p{N}]/gu, '');

async function keyApiRoute(req, env, ctx, u, key, ep) {
  const H = { 'content-type': 'application/json;charset=utf-8', 'access-control-allow-origin': '*', 'cache-control': 'no-store' };
  const J = (o, s) => new Response(JSON.stringify(o), { status: s || 200, headers: H });
  if (req.method === 'OPTIONS') return new Response(null, { status: 204, headers: Object.assign({}, H, { 'access-control-allow-methods': 'GET,OPTIONS', 'access-control-allow-headers': '*' }) });
  if (req.method !== 'GET' && req.method !== 'HEAD') return J({ ok: false, error: 'method_not_allowed' }, 405);
  let c; try { c = await kCheck(env, key); } catch { return J({ ok: false, error: 'db_error' }, 503); }
  if (c.s !== 200) return J({ ok: false, error: c.e }, c.s);
  if (ctx && ctx.waitUntil) ctx.waitUntil(env.BP_DB.prepare('UPDATE bp_keys SET total = total + 1, today = CASE WHEN day = ?1 THEN today + 1 ELSE 1 END, day = ?1, last = ?3 WHERE k = ?2').bind(c.d, key, Math.floor(Date.now() / 1000)).run().catch(() => { }));

  const origin = u.origin, q = u.searchParams;
  const rs = await Promise.allSettled([fcGet(origin), mmGet(env, origin), ixGet(origin)]);
  if (rs.every(r => r.status === 'rejected')) return J({ ok: false, error: 'upstream', result: [] }, 502);
  const all = [];
  rs.forEach(r => { if (r.status === 'fulfilled') all.push(...r.value); });
  all.sort((a, b) => (b.live - a.live) || ((a.startAt || 9e12) - (b.startAt || 9e12)));
  const done = l => J({ ok: true, total: l.length, result: l });

  if (ep === 'home') return done(q.get('live') === '1' ? all.filter(m => m.live) : all);
  if (ep === 'live') return done(all.filter(m => m.live));
  if (ep === 'search') {
    const kw = nzs(q.get('q'));
    if (kw.length < 2) return J({ ok: false, error: 'q_required', hint: 'search?q=arkei (အနည်းဆုံး ၂ လုံး)' }, 400);
    return done(all.filter(m => [m.league.name, m.league.my, m.home.name, m.home.my, m.away.name, m.away.my].some(x => x && nzs(x).includes(kw))));
  }
  if (ep === 'match') {
    const m = all.find(x => x.id === (q.get('id') || '').trim());
    return m ? J({ ok: true, result: m }) : J({ ok: false, error: 'not_found' }, 404);
  }
  return J({ ok: false, error: 'not_found', endpoints: ['home', 'live', 'search?q=', 'match?id='] }, 404);
}

