<div id="chips" class="flex gap-2 overflow-x-auto pb-3 -mx-4 px-4 [scrollbar-width:none]">${chip('all', 'All')}${chip('active', 'Active')}${chip('off', 'Disabled')}${chip('expired', 'Expired')}</div>
