  async function api(t, p) { const q = new URLSearchParams(Object.assign({ t }, p)); try { const r = await fetch('/api?' + q, { headers: { 'x-init': INIT } }); if (r.status === 403) { gate(); return null } if (!r.ok) throw 0; return await r.json() } catch (_) { return null } }
  function toast(t, ms) { const e = $('toast'); e.textContent = t; e.classList.remove('opacity-0', 'translate-y-4'); clearTimeout(toast.t); toast.t = setTimeout(() => e.classList.add('opacity-0', 'translate-y-4'), ms || 2400) }

  /* ---------- FotMob match data ---------- */
  const phase = s => s && s.cancelled ? 'X' : s && s.finished ? 'FT' : s && s.started ? (s.reason && s.reason.short === 'HT' ? 'HT' : 'LIVE') : 'NS';
