const BP_3D_JS = `(function(){
if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;
var cur=null,pend=null,raf=0,KEYS=['--rx','--ry','--mx','--my','--gx','--gy'];
function apply(){raf=0;var p=pend;if(!p)return;var el=p.el;if(!document.body.contains(el)){cur=null;pend=null;return}
var r=el.getBoundingClientRect();if(!r.width||!r.height)return;
var x=Math.max(0,Math.min(1,(p.x-r.left)/r.width)),y=Math.max(0,Math.min(1,(p.y-r.top)/r.height)),m=el.id==='pl'?3:8,s=el.style;
s.setProperty('--ry',((x-.5)*2*m).toFixed(2)+'deg');s.setProperty('--rx',((.5-y)*2*m).toFixed(2)+'deg');
s.setProperty('--mx',((x-.5)*2).toFixed(3));s.setProperty('--my',((y-.5)*2).toFixed(3));
s.setProperty('--gx',(x*100).toFixed(1)+'%');s.setProperty('--gy',(y*100).toFixed(1)+'%')}
function off(){if(!cur)return;var el=cur;cur=null;pend=null;el.classList.remove('t3on');KEYS.forEach(function(k){el.style.removeProperty(k)})}
document.addEventListener('pointermove',function(e){
if(e.pointerType!=='mouse'&&e.pointerType!=='pen')return;
var el=e.target.closest?e.target.closest('.mc,#pl'):null;
if(el&&el.id==='pl'&&el.classList.contains('fs'))el=null;
if(el!==cur){off();if(el){cur=el;el.classList.add('t3on')}}
if(cur){pend={el:cur,x:e.clientX,y:e.clientY};if(!raf)raf=requestAnimationFrame(apply)}},{passive:true});
/* Touch devices: never run per-card 3D tracking while scrolling. */
if(matchMedia('(hover: hover) and (pointer: fine)').matches){
['pointerup','pointercancel'].forEach(function(n){document.addEventListener(n,function(){off()},{passive:true})});
}else{off()}
document.documentElement.addEventListener('mouseleave',off);window.addEventListener('blur',off);
})();`;

